import './styles.css';
import { useState } from 'react';

// Simulated AI "brain" - learns from examples
type ShapeType = 'circle' | 'square';
type ColorType = 'red' | 'blue' | 'green';

interface TrainingExample {
  id: number;
  shape: ShapeType;
  color: ColorType;
  category: 'Category A' | 'Category B';
}

interface TestShape {
  id: number;
  shape: ShapeType;
  color: ColorType;
}

// Generate random shapes for testing
function generateTestShapes(): TestShape[] {
  const shapes: ShapeType[] = ['circle', 'square'];
  const colors: ColorType[] = ['red', 'blue', 'green'];

  return Array.from({ length: 6 }, (_, i) => ({
    id: i,
    shape: shapes[Math.floor(Math.random() * shapes.length)],
    color: colors[Math.floor(Math.random() * colors.length)],
  }));
}

// Simple shape component
function Shape({ shape, color, size = 60 }: { shape: ShapeType; color: ColorType; size?: number }) {
  const colorMap = {
    red: '#ef4444',
    blue: '#3b82f6',
    green: '#22c55e',
  };

  if (shape === 'circle') {
    return (
      <div
        className="shape"
        style={{
          width: size,
          height: size,
          backgroundColor: colorMap[color],
          borderRadius: '50%',
        }}
      />
    );
  }

  return (
    <div
      className="shape"
      style={{
        width: size,
        height: size,
        backgroundColor: colorMap[color],
        borderRadius: 8,
      }}
    />
  );
}

// Training phase component
function TrainingPhase({
  examples,
  onComplete,
}: {
  examples: TrainingExample[];
  onComplete: () => void;
}) {
  return (
    <div className="phase">
      <div className="phase-header">
        <span className="phase-badge">Step 1: Training</span>
        <h2>Teach the AI</h2>
        <p>Look at these examples. The AI is learning what makes something Category A vs Category B.</p>
      </div>

      <div className="training-grid">
        <div className="category-column">
          <h3 className="category-title category-a">Category A</h3>
          <div className="examples">
            {examples
              .filter((e) => e.category === 'Category A')
              .map((example) => (
                <div key={example.id} className="example-card">
                  <Shape shape={example.shape} color={example.color} />
                  <span className="shape-label">{example.color} {example.shape}</span>
                </div>
              ))}
          </div>
        </div>

        <div className="category-column">
          <h3 className="category-title category-b">Category B</h3>
          <div className="examples">
            {examples
              .filter((e) => e.category === 'Category B')
              .map((example) => (
                <div key={example.id} className="example-card">
                  <Shape shape={example.shape} color={example.color} />
                  <span className="shape-label">{example.color} {example.shape}</span>
                </div>
              ))}
          </div>
        </div>
      </div>

      <div className="hint-box">
        <strong>Hint:</strong> Can you spot the pattern? What do all Category A shapes have in common?
      </div>

      <button className="primary-btn" onClick={onComplete}>
        I see the pattern! Test the AI
      </button>
    </div>
  );
}

// Testing phase component
function TestingPhase({
  testShapes,
  predictions,
  rule,
  onPredict,
  onReveal,
  revealed,
}: {
  testShapes: TestShape[];
  predictions: Record<number, 'Category A' | 'Category B' | null>;
  rule: (shape: TestShape) => 'Category A' | 'Category B';
  onPredict: (id: number, category: 'Category A' | 'Category B') => void;
  onReveal: () => void;
  revealed: boolean;
}) {
  return (
    <div className="phase">
      <div className="phase-header">
        <span className="phase-badge">Step 2: Testing</span>
        <h2>Predict Like the AI</h2>
        <p>Based on the pattern you noticed, classify these new shapes.</p>
      </div>

      <div className="test-grid">
        {testShapes.map((shape) => {
          const prediction = predictions[shape.id];
          const actual = rule(shape);
          const isCorrect = prediction === actual;

          return (
            <div key={shape.id} className="test-card">
              <Shape shape={shape.shape} color={shape.color} size={70} />
              <span className="shape-label">{shape.color} {shape.shape}</span>

              {!revealed ? (
                <div className="prediction-buttons">
                  <button
                    className={`pred-btn ${prediction === 'Category A' ? 'selected-a' : ''}`}
                    onClick={() => onPredict(shape.id, 'Category A')}
                  >
                    A
                  </button>
                  <button
                    className={`pred-btn ${prediction === 'Category B' ? 'selected-b' : ''}`}
                    onClick={() => onPredict(shape.id, 'Category B')}
                  >
                    B
                  </button>
                </div>
              ) : (
                <div className={`result ${isCorrect ? 'correct' : 'incorrect'}`}>
                  {isCorrect ? 'Correct!' : `Actually ${actual}`}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {!revealed && (
        <button
          className="primary-btn"
          onClick={onReveal}
          disabled={Object.values(predictions).some((p) => p === null)}
        >
          Check My Predictions
        </button>
      )}
    </div>
  );
}

// Results component
function Results({
  score,
  total,
  ruleDescription,
  onRestart,
}: {
  score: number;
  total: number;
  ruleDescription: string;
  onRestart: () => void;
}) {
  const percentage = Math.round((score / total) * 100);

  return (
    <div className="results-section">
      <h2>Results</h2>
      <div className="score-display">
        <span className="score-number">{score}/{total}</span>
        <span className="score-label">correct predictions</span>
      </div>

      <div className="rule-reveal">
        <h3>The Pattern Was:</h3>
        <p className="rule-text">{ruleDescription}</p>
      </div>

      <div className="insight-box">
        <h4>How This Relates to AI</h4>
        <p>
          Real AI works similarly! It examines thousands of examples, finds patterns in the data,
          and uses those patterns to classify new things it hasn't seen before.
        </p>
        <p>
          The difference is that AI finds these patterns mathematically, often discovering
          patterns too subtle for humans to notice.
        </p>
      </div>

      <button className="primary-btn" onClick={onRestart}>
        Try Another Pattern
      </button>
    </div>
  );
}

// Main App
export default function App() {
  // Different rules to learn
  const rules = [
    {
      name: 'shape',
      description: 'Category A = Circles, Category B = Squares',
      fn: (s: TestShape): 'Category A' | 'Category B' => s.shape === 'circle' ? 'Category A' : 'Category B',
    },
    {
      name: 'color',
      description: 'Category A = Blue shapes, Category B = Non-blue shapes',
      fn: (s: TestShape): 'Category A' | 'Category B' => s.color === 'blue' ? 'Category A' : 'Category B',
    },
    {
      name: 'redSquare',
      description: 'Category A = Red OR Square shapes, Category B = Everything else',
      fn: (s: TestShape): 'Category A' | 'Category B' => (s.color === 'red' || s.shape === 'square') ? 'Category A' : 'Category B',
    },
  ];

  const [ruleIndex, setRuleIndex] = useState(0);
  const currentRule = rules[ruleIndex];

  // Generate training examples based on the current rule
  const generateTrainingExamples = (): TrainingExample[] => {
    const examples: TrainingExample[] = [];
    const shapes: ShapeType[] = ['circle', 'square'];
    const colors: ColorType[] = ['red', 'blue', 'green'];
    let id = 0;

    shapes.forEach((shape) => {
      colors.forEach((color) => {
        const testShape = { id, shape, color };
        examples.push({
          ...testShape,
          category: currentRule.fn(testShape),
        });
        id++;
      });
    });

    return examples;
  };

  const [phase, setPhase] = useState<'training' | 'testing' | 'results'>('training');
  const [trainingExamples] = useState(generateTrainingExamples);
  const [testShapes, setTestShapes] = useState(generateTestShapes);
  const [predictions, setPredictions] = useState<Record<number, 'Category A' | 'Category B' | null>>(
    Object.fromEntries(testShapes.map((s) => [s.id, null]))
  );
  const [revealed, setRevealed] = useState(false);

  const handlePredict = (id: number, category: 'Category A' | 'Category B') => {
    setPredictions((prev) => ({ ...prev, [id]: category }));
  };

  const handleReveal = () => {
    setRevealed(true);
    setTimeout(() => setPhase('results'), 1500);
  };

  const handleRestart = () => {
    const newRuleIndex = (ruleIndex + 1) % rules.length;
    setRuleIndex(newRuleIndex);
    setPhase('training');
    const newTestShapes = generateTestShapes();
    setTestShapes(newTestShapes);
    setPredictions(Object.fromEntries(newTestShapes.map((s) => [s.id, null])));
    setRevealed(false);
  };

  const score = testShapes.reduce((acc, shape) => {
    return acc + (predictions[shape.id] === currentRule.fn(shape) ? 1 : 0);
  }, 0);

  return (
    <div className="app">
      <div className="header">
        <h1>How AI Sees Patterns</h1>
        <p className="subtitle">
          Discover how artificial intelligence learns to classify things
        </p>
      </div>

      {phase === 'training' && (
        <TrainingPhase
          examples={trainingExamples}
          onComplete={() => setPhase('testing')}
        />
      )}

      {phase === 'testing' && (
        <TestingPhase
          testShapes={testShapes}
          predictions={predictions}
          rule={currentRule.fn}
          onPredict={handlePredict}
          onReveal={handleReveal}
          revealed={revealed}
        />
      )}

      {phase === 'results' && (
        <Results
          score={score}
          total={testShapes.length}
          ruleDescription={currentRule.description}
          onRestart={handleRestart}
        />
      )}
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 900px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 2rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: #94a3b8;
  font-size: 1rem;
}

.phase {
  background: white;
  border-radius: 1rem;
  padding: 2rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.phase-header {
  text-align: center;
  margin-bottom: 2rem;
}

.phase-badge {
  display: inline-block;
  background: #dbeafe;
  color: #1d4ed8;
  padding: 0.25rem 0.75rem;
  border-radius: 1rem;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 0.75rem;
}

.phase-header h2 {
  color: #1f2937;
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
}

.phase-header p {
  color: #6b7280;
}

.training-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 1.5rem;
}

.category-column {
  text-align: center;
}

.category-title {
  font-size: 1rem;
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  margin-bottom: 1rem;
}

.category-title.category-a {
  background: #dbeafe;
  color: #1d4ed8;
}

.category-title.category-b {
  background: #fce7f3;
  color: #be185d;
}

.examples {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.example-card {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 0.75rem;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.shape {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.shape-label {
  font-size: 0.75rem;
  color: #6b7280;
  text-transform: capitalize;
}

.hint-box {
  background: #fef3c7;
  border: 1px solid #fcd34d;
  border-radius: 0.5rem;
  padding: 1rem;
  margin-bottom: 1.5rem;
  color: #92400e;
  font-size: 0.9rem;
}

.primary-btn {
  width: 100%;
  padding: 1rem;
  background: linear-gradient(135deg, #3b82f6 0%, #6366f1 100%);
  color: white;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.primary-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(59, 130, 246, 0.4);
}

.primary-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* Testing Phase */
.test-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.test-card {
  background: #f9fafb;
  border: 2px solid #e5e7eb;
  border-radius: 0.75rem;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
}

.prediction-buttons {
  display: flex;
  gap: 0.5rem;
}

.pred-btn {
  width: 40px;
  height: 40px;
  border: 2px solid #d1d5db;
  background: white;
  border-radius: 0.5rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.pred-btn:hover {
  border-color: #9ca3af;
}

.pred-btn.selected-a {
  background: #dbeafe;
  border-color: #3b82f6;
  color: #1d4ed8;
}

.pred-btn.selected-b {
  background: #fce7f3;
  border-color: #ec4899;
  color: #be185d;
}

.result {
  font-size: 0.875rem;
  font-weight: 600;
  padding: 0.25rem 0.75rem;
  border-radius: 1rem;
}

.result.correct {
  background: #d1fae5;
  color: #065f46;
}

.result.incorrect {
  background: #fee2e2;
  color: #991b1b;
}

/* Results */
.results-section {
  background: white;
  border-radius: 1rem;
  padding: 2rem;
  text-align: center;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.results-section h2 {
  color: #1f2937;
  margin-bottom: 1.5rem;
}

.score-display {
  margin-bottom: 2rem;
}

.score-number {
  font-size: 3rem;
  font-weight: 700;
  color: #3b82f6;
}

.score-label {
  display: block;
  color: #6b7280;
  font-size: 0.9rem;
}

.rule-reveal {
  background: #f0fdf4;
  border: 1px solid #86efac;
  border-radius: 0.75rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}

.rule-reveal h3 {
  color: #166534;
  font-size: 0.9rem;
  text-transform: uppercase;
  margin-bottom: 0.5rem;
}

.rule-text {
  color: #15803d;
  font-size: 1.1rem;
  font-weight: 500;
}

.insight-box {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  border-radius: 0.75rem;
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  text-align: left;
}

.insight-box h4 {
  color: #1d4ed8;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #1e40af;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .training-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .test-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
